package com.codearena.submission;
import com.codearena.common.domain.*; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="submissions",indexes={@Index(name="idx_submission_student_created",columnList="studentId,createdAt"),@Index(name="idx_submission_problem",columnList="problemId")}) public class Submission { @Id @GeneratedValue(strategy=GenerationType.UUID) public UUID id; @Column(nullable=false) public UUID studentId; @Column(nullable=false) public UUID problemId; public UUID contestId; @Column(nullable=false) public String language; @Column(nullable=false,columnDefinition="text") public String sourceCode; @Enumerated(EnumType.STRING) @Column(nullable=false) public SubmissionStatus status=SubmissionStatus.CREATED; @Enumerated(EnumType.STRING) @Column(nullable=false) public Verdict verdict=Verdict.PENDING; public Long executionTimeMs; public Long memoryUsageKb; public Integer score; @Column(nullable=false) public Instant createdAt=Instant.now(); }
